    function setStatus(market, state, label) {
        const dot = document.getElementById(`dot-${market}`);
        const text = document.getElementById(`status-${market}-text`);
        if (!dot) return;
        dot.className = `status-dot status-${state}`;
        if (text) text.innerText = label || state;
    }

    function showToast(message, tone = 'info') {
        const toneMap = {
            success: { color: 'var(--cw-green)', icon: '✓' },
            error: { color: 'var(--cw-red)', icon: '✕' },
            info: { color: 'var(--cw-cyan)', icon: 'ℹ' },
        };
        const { color, icon } = toneMap[tone] || toneMap.info;
        const el = document.createElement('div');
        el.className = 'toast-enter cw-toast rounded-lg pr-4 py-2.5 text-xs shadow-2xl max-w-xs border border-gray-800';
        el.style.setProperty('--cw-tone', color);
        const iconEl = document.createElement('span');
        iconEl.className = 'cw-toast-icon text-[13px]';
        iconEl.innerText = icon;
        const msgEl = document.createElement('span');
        msgEl.className = 'font-mono leading-snug pt-px';
        msgEl.style.color = color;
        msgEl.innerText = message; // user-supplied fragments (e.g. typed symbols) land here — never innerHTML
        el.appendChild(iconEl);
        el.appendChild(msgEl);
        document.getElementById('toast-container').appendChild(el);
        setTimeout(() => { el.style.transition = 'opacity 0.4s, transform 0.4s'; el.style.opacity = '0'; el.style.transform = 'translateX(16px)'; setTimeout(() => el.remove(), 400); }, 4500);
    }

    function formatCompact(num) {
        if (num === null || num === undefined || isNaN(num)) return '--';
        const abs = Math.abs(num);
        if (abs >= 1e9) return (num / 1e9).toFixed(2) + 'B';
        if (abs >= 1e6) return (num / 1e6).toFixed(2) + 'M';
        if (abs >= 1e3) return (num / 1e3).toFixed(2) + 'K';
        return num.toFixed(2);
    }

    function priceFmt(price) {
        return price < 1 ? { minimumFractionDigits: 4, maximumFractionDigits: 6 } : { minimumFractionDigits: 2, maximumFractionDigits: 2 };
    }

    // ---------- Bootstrapping market data ----------
    // Spot and futures are fetched fully independently (each with its own try/catch) so a
    // network/CORS/regional failure on ONE leg — most commonly the futures API — can never
    // take down the other. Previously both fetches shared a single Promise.all with no inner
    // catch, so any futures-side network error rejected the whole thing and produced
    // "Could not reach Binance market data" even when spot was reachable. That was the bug.


// ==== 02-api.js ====
// ---------- REST calls: Binance snapshots, global market pulse (CoinGecko + Fear & Greed), trending coins. ----------
    async function fetchSpotSnapshot() {
        try {
            const res = await fetchWithTimeout('https://api.binance.com/api/v3/ticker/24hr');
            return await parseBinanceJSON(res, 'Spot');
        } catch (err) {
            console.warn('Spot 24hr ticker unavailable:', err.message);
            setStatus('spot', 'error', 'Unavailable');
            return null; // null = hard failure, distinct from [] = fetched but empty
        }
    }

    async function fetchFuturesSnapshot() {
        try {
            const res = await fetchWithTimeout('https://fapi.binance.com/fapi/v1/ticker/24hr');
            return await parseBinanceJSON(res, 'Futures');
        } catch (err) {
            console.warn('Futures 24hr ticker unavailable:', err.message);
            setStatus('futures', 'error', 'Unavailable');
            return null;
        }
    }

    async function initMasterTerminalData() {
        try {
            // Both legs run in parallel, but each is caught inside its own function above —
            // one rejecting never affects the other.
            const [spotRaw, futuresRaw] = await Promise.all([
                fetchSpotSnapshot(),
                fetchFuturesSnapshot()
            ]);

            if (spotRaw === null && futuresRaw === null) {
                throw new Error('Both spot and futures endpoints were unreachable.');
            }
            if (spotRaw === null) {
                showToast('Spot market data unavailable right now. Showing futures only.', 'error');
            }
            if (futuresRaw === null) {
                showToast('Futures market data unavailable right now. Spot data still live.', 'error');
            }

            marketMap = {};

            const processData = (arr, isFutures) => {
                if (!Array.isArray(arr)) return;
                arr.filter(item => item && typeof item.symbol === 'string' && item.symbol.endsWith('USDT')).forEach(item => {
                    const idKey = `${item.symbol.toUpperCase()}_${isFutures ? 'F' : 'S'}`;
                    marketMap[idKey] = {
                        id: idKey,
                        symbol: item.symbol.toUpperCase(),
                        baseAsset: item.symbol.toUpperCase().replace('USDT', ''),
                        price: parseFloat(item.lastPrice) || 0,
                        changePct: parseFloat(item.priceChangePercent) || 0,
                        high: parseFloat(item.highPrice) || 0,
                        low: parseFloat(item.lowPrice) || 0,
                        volume: parseFloat(item.quoteVolume) || 0,
                        isFutures: isFutures,
                        domId: `row_${idKey.replace(/[@#]/g, '_')}`
                    };
                });
            };

            if (spotRaw) processData(spotRaw, false);
            if (futuresRaw) processData(futuresRaw, true);

            if (Object.keys(marketMap).length === 0) {
                throw new Error('No market symbols were returned.');
            }

            refreshArrayDataList();
            renderTableHTMLStructure();
            updateMoverStrip();
            populateSymbolDatalists();
            renderPopularCoinsStrip();
            renderPortfolio();
            renderFuturesPositions();
            setInterval(updateMoverStrip, 15000);

            fetchGlobalMarketPulse();
            fetchTrendingCoins();
            setInterval(fetchGlobalMarketPulse, 60000);
            setInterval(fetchTrendingCoins, 120000);

            loading.classList.add('hidden');
            initError.classList.add('hidden');
            tableContainer.classList.remove('hidden');

            if (globalMarketList.length > 0 && !selectedAsset) {
                let defaultAsset = null;
                if (lastSelection && marketMap[lastSelection.id]) {
                    defaultAsset = marketMap[lastSelection.id];
                    if (lastSelection.interval) currentInterval = lastSelection.interval;
                    syncIntervalButtons();
                } else {
                    defaultAsset = globalMarketList.find(a => a.symbol === 'BTCUSDT' && !a.isFutures) || globalMarketList[0];
                }
                selectAsset(defaultAsset);
            }

            connectGlobalPriceTickerStreams();

        } catch (error) {
            console.error("Initialization pipeline failed, retrying in 5s...", error);
            loading.classList.add('hidden');
            initError.classList.remove('hidden');
            setStatus('spot', 'error', 'Retrying');
            setStatus('futures', 'error', 'Retrying');
            setTimeout(initMasterTerminalData, 5000);
        }
    }

    async function fetchWithTimeout(url, ms = 10000) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), ms);
    try {
        // Binance's public REST endpoints allow direct browser calls (CORS-enabled) —
        // no proxy needed here. Only the AI insight endpoint goes through our own backend.
        return await fetch(url, { signal: controller.signal });
    } finally {
        clearTimeout(timer);
    }
}

    async function parseBinanceJSON(res, label) {
        if (!res.ok) throw new Error(`${label} API responded with status ${res.status}`);
        const data = await res.json();
        if (data && !Array.isArray(data) && data.code) {
            throw new Error(`${label} API error ${data.code}: ${data.msg || 'unknown error'}`);
        }
        if (!Array.isArray(data)) throw new Error(`${label} API returned an unexpected payload.`);
        return data;
    }

    function syncIntervalButtons() {
        document.querySelectorAll('.tf-btn').forEach(btn => {
            btn.classList.toggle('active', btn.getAttribute('data-tf') === currentInterval);
        });
    }

    function refreshArrayDataList() {
        globalMarketList = Object.values(marketMap).sort((a, b) => b.volume - a.volume);
    }

    // ---------- Global Market Pulse (CoinGecko + Alternative.me — independent of Binance) ----------
    async function fetchGlobalMarketPulse() {
        try {
            const res = await fetchWithTimeout('https://api.coingecko.com/api/v3/global', 10000);
            if (!res.ok) throw new Error(`CoinGecko global responded ${res.status}`);
            const json = await res.json();
            const d = json.data;
            if (!d) return;

            document.getElementById('pulse-mcap').innerText = `$${formatCompact(d.total_market_cap.usd)}`;
            document.getElementById('pulse-vol').innerText = `$${formatCompact(d.total_volume.usd)}`;
            document.getElementById('pulse-btcdom').innerText = `${d.market_cap_percentage.btc.toFixed(1)}%`;

            const chgEl = document.getElementById('pulse-mcap-chg');
            const chg = d.market_cap_change_percentage_24h_usd;
            if (typeof chg === 'number') {
                chgEl.innerText = `${chg >= 0 ? '+' : ''}${chg.toFixed(2)}%`;
                chgEl.className = `text-[10px] font-mono font-bold ml-1 ${chg >= 0 ? 'text-[#14d38a]' : 'text-[#ff4d6a]'}`;
            }
        } catch (e) {
            console.warn('Global market pulse unavailable:', e.message);
        }

        try {
            const res = await fetchWithTimeout('https://api.alternative.me/fng/?limit=1', 10000);
            if (!res.ok) throw new Error(`Fear & Greed API responded ${res.status}`);
            const json = await res.json();
            const entry = json.data && json.data[0];
            if (!entry) return;
            const val = parseInt(entry.value, 10);
            document.getElementById('pulse-fng-value').innerText = val;
            const labelEl = document.getElementById('pulse-fng-label');
            labelEl.innerText = entry.value_classification;
            const color = val <= 24 ? 'text-[#ff4d6a] border-[#ff4d6a]/40' : val <= 44 ? 'text-amber-400 border-amber-400/40' : val <= 55 ? 'text-gray-300 border-gray-600' : val <= 75 ? 'text-[#14d38a] border-[#14d38a]/40' : 'text-[#14d38a] border-[#14d38a]/60';
            labelEl.className = `text-[9px] font-bold uppercase px-2 py-1 rounded border ${color}`;
        } catch (e) {
            console.warn('Fear & Greed index unavailable:', e.message);
        }
    }

    async function fetchTrendingCoins() {
        const strip = document.getElementById('trending-coins-strip');
        try {
            const res = await fetchWithTimeout('https://api.coingecko.com/api/v3/search/trending', 10000);
            if (!res.ok) throw new Error(`Trending API responded ${res.status}`);
            const json = await res.json();
            const coins = (json.coins || []).slice(0, 7).map(c => c.item);
            if (coins.length === 0) { strip.innerHTML = '<span class="text-gray-600 text-[10px]">No trending data.</span>'; return; }

            strip.innerHTML = coins.map(c => {
                const sym = (c.symbol || '').toUpperCase();
                const tracked = !!(marketMap[`${sym}USDT_S`] || marketMap[`${sym}USDT_F`]);
                return `<button class="trending-chip text-[10px] px-2 py-1 rounded-full border transition-all cursor-pointer flex items-center gap-1 ${tracked ? 'bg-gray-900 border-gray-800/80 text-gray-300 hover:border-[#14d38a]/50' : 'bg-gray-900/50 border-gray-800/40 text-gray-600 cursor-default'}" data-sym="${sym}" ${tracked ? '' : 'disabled'}>
                    #${c.market_cap_rank || '?'} <span class="font-bold">${sym}</span>
                </button>`;
            }).join('');

            strip.querySelectorAll('.trending-chip:not([disabled])').forEach(chip => {
                chip.addEventListener('click', () => {
                    const sym = chip.getAttribute('data-sym');
                    const asset = marketMap[`${sym}USDT_S`] || marketMap[`${sym}USDT_F`];
                    if (asset) { selectAsset(asset); searchInput.value = ''; renderTableHTMLStructure(); }
                });
            });
        } catch (e) {
            console.warn('Trending coins unavailable:', e.message);
            strip.innerHTML = '<span class="text-gray-600 text-[10px]">Unavailable right now.</span>';
        }
    }

    function updateMoverStrip() {
        if (globalMarketList.length === 0) return;
        const sorted = [...globalMarketList].filter(a => a.volume > 1000000).sort((a, b) => b.changePct - a.changePct);
        const gainers = sorted.slice(0, 6);
        const losers = sorted.slice(-6).reverse();
        const items = [...gainers, ...losers];
        const strip = document.getElementById('mover-strip');
        const buildChip = (item) => {
            const color = item.changePct >= 0 ? 'text-[#14d38a]' : 'text-[#ff4d6a]';
            const tag = item.isFutures ? 'Perp' : 'Spot';
            return `<span class="inline-flex items-center gap-1.5 px-4"><span class="text-gray-300 font-bold">${item.baseAsset}</span><span class="text-gray-600 text-[9px]">${tag}</span><span class="${color} font-bold">${item.changePct >= 0 ? '+' : ''}${item.changePct.toFixed(2)}%</span></span>`;
        };
        const htmlChunk = items.map(buildChip).join('');
        strip.innerHTML = htmlChunk + htmlChunk; // duplicate for seamless marquee loop
        gridCount.innerText = `${globalMarketList.length} markets tracked`;
    }



// ==== 03-ui-table.js ====
// ---------- Market table rendering, CSV export, symbol datalists, popular-coin strip, watchlist toggling. ----------
    function renderTableHTMLStructure() {
        const term = searchInput.value.toUpperCase().trim();
        cryptoRows.innerHTML = '';

        let filtered = globalMarketList.filter(item => 
            item.symbol.includes(term) || item.baseAsset.includes(term)
        );

        if (currentFilter === 'spot') filtered = filtered.filter(item => !item.isFutures);
        if (currentFilter === 'futures') filtered = filtered.filter(item => item.isFutures);
        if (currentFilter === 'watchlist') filtered = filtered.filter(item => watchlist.includes(item.id));
        if (currentFilter === 'gainers') filtered = [...filtered].filter(i => i.volume > 500000).sort((a, b) => b.changePct - a.changePct);
        if (currentFilter === 'losers') filtered = [...filtered].filter(i => i.volume > 500000).sort((a, b) => a.changePct - b.changePct);

        filtered.slice(0, 100).forEach(item => {
            const row = document.createElement('tr');
            row.id = item.domId;
            row.className = `hover:bg-gray-800/40 transition-colors border-b border-gray-800/30 ${selectedAsset && selectedAsset.id === item.id ? 'active-row' : ''}`;
            
            const badgeColor = item.isFutures ? 'bg-amber-500/10 text-amber-500 border border-amber-500/20' : 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20';
            const isStarred = watchlist.includes(item.id);

            row.innerHTML = `
                <td class="py-3 px-4 text-center star-cell cursor-pointer text-sm select-none ${isStarred ? 'text-amber-400' : 'text-gray-600 hover:text-gray-400'}">
                    ${isStarred ? '★' : '☆'}
                </td>
                <td class="py-3 px-2 main-click-zone">
                    <div class="flex items-center gap-2">
                        <span class="font-bold text-white tracking-wide">${item.baseAsset}</span>
                        <span class="text-[9px] font-mono tracking-wider font-bold px-1.5 py-0.5 rounded uppercase ${badgeColor}">
                            ${item.isFutures ? 'Perp' : 'Spot'}
                        </span>
                    </div>
                </td>
                <td class="py-3 px-3 text-right text-gray-100 price-cell main-click-zone">$${item.price.toLocaleString(undefined, priceFmt(item.price))}</td>
                <td class="py-3 px-3 text-right text-gray-500 volume-cell main-click-zone hidden md:table-cell">$${formatCompact(item.volume)}</td>
                <td class="py-3 px-4 text-right font-bold change-cell main-click-zone ${item.changePct >= 0 ? 'text-[#14d38a]' : 'text-[#ff4d6a]'}">
                    ${item.changePct >= 0 ? '+' : ''}${item.changePct.toFixed(2)}%
                </td>
            `;

            // Separate Watchlist click bounds from selection row mechanism
            row.querySelector('.star-cell').addEventListener('click', (e) => {
                e.stopPropagation();
                toggleWatchlistAsset(item.id, e.target);
            });

            row.querySelectorAll('.main-click-zone').forEach(cell => {
                cell.addEventListener('click', () => selectAsset(item));
            });

            cryptoRows.appendChild(row);
        });

        if (filtered.length === 0) {
            cryptoRows.innerHTML = `<tr><td colspan="5" class="py-10 text-center text-gray-600 text-[11px]">No assets match this filter.</td></tr>`;
        }

        renderMarketHeatmap();
    }

    // ---------- Market Heatmap ----------
    // A quick-scan color grid of 24h performance — deliberately simple tiles (not a
    // proportional treemap) so it stays fast and legible even with dozens of assets.
    let heatmapScope = 'volume';
    function heatmapColorFor(changePct) {
        const clamped = Math.max(-8, Math.min(8, changePct));
        if (clamped >= 0) {
            const alpha = 0.15 + (clamped / 8) * 0.55;
            return `rgba(20, 211, 138, ${alpha.toFixed(2)})`;
        }
        const alpha = 0.15 + (Math.abs(clamped) / 8) * 0.55;
        return `rgba(255, 77, 106, ${alpha.toFixed(2)})`;
    }

    function renderMarketHeatmap() {
        const container = document.getElementById('market-heatmap');
        if (!container) return;

        let pool = heatmapScope === 'watchlist'
            ? globalMarketList.filter(item => watchlist.includes(item.id))
            : [...globalMarketList].filter(i => i.volume > 500000);

        pool = [...pool].sort((a, b) => b.volume - a.volume).slice(0, 24);

        if (pool.length === 0) {
            container.innerHTML = heatmapScope === 'watchlist'
                ? '<p class="col-span-full text-gray-600 text-[10.5px] py-8 text-center">Star some assets in the table above to see them here.</p>'
                : '<p class="col-span-full text-gray-600 text-[10.5px] py-8 text-center">Waiting for market data...</p>';
            return;
        }

        container.innerHTML = pool.map(item => `
            <div class="heatmap-tile rounded px-1.5 py-2 cursor-pointer flex flex-col items-center justify-center gap-0.5 border border-white/5 hover:border-white/20 transition-all"
                 style="background-color:${heatmapColorFor(item.changePct)};" data-id="${item.id}" title="${item.baseAsset}/USDT — $${item.price.toLocaleString(undefined, priceFmt(item.price))}">
                <span class="text-[10px] font-bold text-white truncate max-w-full">${item.baseAsset}</span>
                <span class="text-[9px] font-mono ${item.changePct >= 0 ? 'text-emerald-200' : 'text-red-200'}">${item.changePct >= 0 ? '+' : ''}${item.changePct.toFixed(1)}%</span>
            </div>
        `).join('');

        container.querySelectorAll('.heatmap-tile').forEach(tile => {
            tile.addEventListener('click', () => {
                const asset = marketMap[tile.getAttribute('data-id')];
                if (asset) { selectAsset(asset); renderTableHTMLStructure(); }
            });
        });
    }

    document.querySelectorAll('.heatmap-scope-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            heatmapScope = btn.getAttribute('data-scope');
            document.querySelectorAll('.heatmap-scope-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            renderMarketHeatmap();
        });
    });

    // ---------- CSV export ----------
    function exportVisibleRowsToCSV() {
        const term = searchInput.value.toUpperCase().trim();
        let filtered = globalMarketList.filter(item => item.symbol.includes(term) || item.baseAsset.includes(term));
        if (currentFilter === 'spot') filtered = filtered.filter(item => !item.isFutures);
        if (currentFilter === 'futures') filtered = filtered.filter(item => item.isFutures);
        if (currentFilter === 'watchlist') filtered = filtered.filter(item => watchlist.includes(item.id));
        if (currentFilter === 'gainers') filtered = [...filtered].filter(i => i.volume > 500000).sort((a, b) => b.changePct - a.changePct);
        if (currentFilter === 'losers') filtered = [...filtered].filter(i => i.volume > 500000).sort((a, b) => a.changePct - b.changePct);

        if (filtered.length === 0) { showToast('Nothing to export for this filter.', 'error'); return; }

        const header = ['Asset', 'Market', 'Symbol', 'Price', 'Volume(USDT)', '24hChange%', '24hHigh', '24hLow'];
        const lines = [header.join(',')];
        filtered.slice(0, 100).forEach(item => {
            lines.push([
                item.baseAsset, item.isFutures ? 'Futures' : 'Spot', item.symbol,
                item.price, item.volume.toFixed(2), item.changePct.toFixed(2), item.high, item.low
            ].join(','));
        });

        const blob = new Blob([lines.join('\n')], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `cryptobolt_${currentFilter}_${Date.now()}.csv`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
        showToast(`Exported ${filtered.slice(0, 100).length} rows to CSV.`, 'success');
    }
    document.getElementById('export-csv-btn').addEventListener('click', exportVisibleRowsToCSV);

    // ---------- Symbol datalists (portfolio + compare autocomplete) ----------
    function populateSymbolDatalists() {
        const bases = Array.from(new Set(globalMarketList.filter(a => !a.isFutures).map(a => a.baseAsset))).sort();
        const futuresBases = Array.from(new Set(globalMarketList.filter(a => a.isFutures).map(a => a.baseAsset))).sort();
        const holdingList = document.getElementById('holding-symbol-list');
        const compareList = document.getElementById('compare-symbol-list');
        const futuresList = document.getElementById('futures-symbol-list');
        const optsHtml = bases.map(b => `<option value="${b}"></option>`).join('');
        if (holdingList) holdingList.innerHTML = optsHtml;
        if (compareList) compareList.innerHTML = optsHtml;
        if (futuresList) futuresList.innerHTML = futuresBases.map(b => `<option value="${b}"></option>`).join('');
    }

    // ---------- Popular coins quick-select ----------
    function renderPopularCoinsStrip() {
        const strip = document.getElementById('popular-coins-strip');
        if (!strip) return;
        const available = POPULAR_COINS.filter(base => marketMap[`${base}USDT_S`] || marketMap[`${base}USDT_F`]);
        strip.innerHTML = available.map(base => {
            const asset = marketMap[`${base}USDT_S`] || marketMap[`${base}USDT_F`];
            const isActive = selectedAsset && selectedAsset.baseAsset === base && !selectedAsset.isFutures === !!marketMap[`${base}USDT_S`];
            const up = asset.changePct >= 0;
            return `<button class="popular-coin-chip text-[11px] px-2.5 py-1 rounded-full border transition-all cursor-pointer flex items-center gap-1.5 ${isActive ? 'bg-[#14d38a] border-[#14d38a] text-[#0b0e11] font-bold' : 'bg-gray-900 border-gray-800/80 text-gray-300 hover:border-gray-600'}" data-base="${base}">
                <span>${base}</span><span class="${isActive ? '' : (up ? 'text-[#14d38a]' : 'text-[#ff4d6a]')} font-mono text-[10px]">${up ? '+' : ''}${asset.changePct.toFixed(1)}%</span>
            </button>`;
        }).join('');

        strip.querySelectorAll('.popular-coin-chip').forEach(chip => {
            chip.addEventListener('click', () => {
                const base = chip.getAttribute('data-base');
                const asset = marketMap[`${base}USDT_S`] || marketMap[`${base}USDT_F`];
                if (asset) {
                    selectAsset(asset);
                    searchInput.value = '';
                    renderTableHTMLStructure();
                }
            });
        });
    }

    function toggleWatchlistAsset(assetId, element) {
        const idx = watchlist.indexOf(assetId);
        if (idx > -1) {
            watchlist.splice(idx, 1);
            element.innerText = '☆';
            element.className = "py-3 px-4 text-center star-cell cursor-pointer text-sm select-none text-gray-600 hover:text-gray-400";
        } else {
            watchlist.push(assetId);
            element.innerText = '★';
            element.className = "py-3 px-4 text-center star-cell cursor-pointer text-sm select-none text-amber-400";
        }
        localStorage.setItem('cw_watchlist', JSON.stringify(watchlist));
        if (currentFilter === 'watchlist') renderTableHTMLStructure();
    }

    // ---------- Global ticker websocket streams (independent spot / futures) ----------


// ==== 04-ticker-sockets.js ====
// ---------- Spot/futures WebSocket ticker streams, reconnect scheduling, live row + HUD updates. ----------
    function connectGlobalPriceTickerStreams() {
        connectSpotTicker();
        connectFuturesTicker();
    }

    function connectSpotTicker() {
        if (spotTickerSocket) { spotTickerSocket.onclose = null; try { spotTickerSocket.close(); } catch (e) {} }
        setStatus('spot', 'connecting', 'Connecting');
        try {
            spotTickerSocket = new WebSocket('wss://stream.binance.com:9443/ws/!ticker@arr');
        } catch (e) {
            setStatus('spot', 'error', 'Failed');
            scheduleSpotReconnect();
            return;
        }
        spotTickerSocket.onopen = () => { setStatus('spot', 'live', 'Live'); spotBackoff = 3000; resetWatchdog('spot'); };
        spotTickerSocket.onmessage = (event) => {
            touchWatchdog('spot');
            let data;
            try { data = JSON.parse(event.data); } catch (e) { return; }
            if (!Array.isArray(data)) return;
            data.forEach(tick => {
                const idKey = `${tick.s.toUpperCase()}_S`;
                if (marketMap[idKey]) {
                    const asset = marketMap[idKey];
                    const oldPrice = asset.price;
                    asset.price = parseFloat(tick.c);
                    asset.changePct = parseFloat(tick.P);
                    asset.high = parseFloat(tick.h);
                    asset.low = parseFloat(tick.l);
                    asset.volume = parseFloat(tick.q);
                    updateDOMRowRealtime(asset, oldPrice);
                    if (selectedAsset && selectedAsset.id === idKey) updateHUDDisplayValues(asset);
                    checkPriceAlerts(asset);
                    checkPositionRiskTriggers(asset);
                }
            });
        };
        spotTickerSocket.onerror = () => { try { spotTickerSocket.close(); } catch (e) {} };
        spotTickerSocket.onclose = () => { setStatus('spot', 'error', 'Reconnecting'); scheduleSpotReconnect(); };
    }

    function connectFuturesTicker() {
        if (futuresTickerSocket) { futuresTickerSocket.onclose = null; try { futuresTickerSocket.close(); } catch (e) {} }
        setStatus('futures', 'connecting', 'Connecting');
        try {
            futuresTickerSocket = new WebSocket('wss://fstream.binance.com/ws/!ticker@arr');
        } catch (e) {
            setStatus('futures', 'error', 'Failed');
            scheduleFuturesReconnect();
            return;
        }
        futuresTickerSocket.onopen = () => { setStatus('futures', 'live', 'Live'); futuresBackoff = 3000; resetWatchdog('futures'); };
        futuresTickerSocket.onmessage = (event) => {
            touchWatchdog('futures');
            let data;
            try { data = JSON.parse(event.data); } catch (e) { return; }
            if (!Array.isArray(data)) return;
            data.forEach(tick => {
                const idKey = `${tick.s.toUpperCase()}_F`; 
                if (marketMap[idKey]) {
                    const asset = marketMap[idKey];
                    const oldPrice = asset.price;
                    asset.price = parseFloat(tick.c);
                    asset.changePct = parseFloat(tick.P);
                    asset.high = parseFloat(tick.h);
                    asset.low = parseFloat(tick.l);
                    asset.volume = parseFloat(tick.q);
                    updateDOMRowRealtime(asset, oldPrice);
                    if (selectedAsset && selectedAsset.id === idKey) updateHUDDisplayValues(asset);
                    checkPriceAlerts(asset);
                    checkPositionRiskTriggers(asset);
                }
            });
        };
        futuresTickerSocket.onerror = () => { try { futuresTickerSocket.close(); } catch (e) {} };
        futuresTickerSocket.onclose = () => { setStatus('futures', 'error', 'Reconnecting'); scheduleFuturesReconnect(); };
    }

    // Adds up to ±20% random jitter to a backoff delay, so reconnect attempts across
    // browser tabs/users don't all land on Binance at the exact same moment.
    function withJitter(delayMs) {
        const jitter = delayMs * 0.2 * (Math.random() * 2 - 1);
        return Math.max(1000, Math.round(delayMs + jitter));
    }

    function scheduleSpotReconnect() {
        if (globalReconnectTimeout) return;
        if (typeof navigator !== 'undefined' && navigator.onLine === false) {
            setStatus('spot', 'error', 'Offline');
            return; // resumed by the 'online' listener in js/12-events-init.js
        }
        globalReconnectTimeout = setTimeout(() => {
            globalReconnectTimeout = null;
            connectSpotTicker();
        }, withJitter(Math.min(spotBackoff *= 1.5, 30000)));
    }
    function scheduleFuturesReconnect() {
        if (futuresReconnectPending) return;
        if (typeof navigator !== 'undefined' && navigator.onLine === false) {
            setStatus('futures', 'error', 'Offline');
            return; // resumed by the 'online' listener in js/12-events-init.js
        }
        futuresReconnectPending = true;
        setTimeout(() => {
            futuresReconnectPending = false;
            connectFuturesTicker();
        }, withJitter(Math.min(futuresBackoff *= 1.5, 30000)));
    }
    let futuresReconnectPending = false;

    function updateDOMRowRealtime(asset, oldPrice) {
        const row = document.getElementById(asset.domId);
        if (!row) return;

        const priceCell = row.querySelector('.price-cell');
        const changeCell = row.querySelector('.change-cell');
        const volumeCell = row.querySelector('.volume-cell');

        if (priceCell && changeCell) {
            priceCell.innerText = `$${asset.price.toLocaleString(undefined, priceFmt(asset.price))}`;
            changeCell.innerText = `${asset.changePct >= 0 ? '+' : ''}${asset.changePct.toFixed(2)}%`;
            changeCell.className = `py-3 px-4 text-right font-bold change-cell ${asset.changePct >= 0 ? 'text-[#14d38a]' : 'text-[#ff4d6a]'}`;
            if (volumeCell) volumeCell.innerText = `$${formatCompact(asset.volume)}`;

            if (asset.price > oldPrice) {
                priceCell.className = "py-3 px-3 text-right font-mono price-cell text-[#14d38a] flash-green";
                setTimeout(() => priceCell.className = "py-3 px-3 text-right font-mono price-cell text-gray-100", 400);
            } else if (asset.price < oldPrice) {
                priceCell.className = "py-3 px-3 text-right font-mono price-cell text-[#ff4d6a] flash-red";
                setTimeout(() => priceCell.className = "py-3 px-3 text-right font-mono price-cell text-gray-100", 400);
            }
        }

        if (!asset.isFutures && holdings.some(h => h.symbol === asset.baseAsset)) renderPortfolio();
        if (asset.isFutures && futuresPositions.some(p => p.symbol === asset.baseAsset)) renderFuturesPositions();
    }

    // ---------- Asset selection ----------
    function selectAsset(item) {
        selectedAsset = item;
        updateHUDDisplayValues(item);
        localStorage.setItem('cw_last_selection', JSON.stringify({ id: item.id, interval: currentInterval }));
        
        document.querySelectorAll('#crypto-rows tr').forEach(r => r.classList.remove('active-row'));
        const activeRow = document.getElementById(item.domId);
        if (activeRow) activeRow.classList.add('active-row');

        initializeAssetChartEngine();
        connectOrderBookStream();
        connectTradesStream();
        startBookAndTradesPolling();
        renderAlertsList();
        startFundingPolling();
        clearCompareOverlay(true);
        renderPopularCoinsStrip();
        resetAIInsightPanel();
        fetchLongTermPerformance(item);
        fetchMultiTimeframeTrend(item);
        renderNotesPanel();
        if (typeof syncRiskCalcForAsset === 'function') syncRiskCalcForAsset();
    }

    function updateHUDDisplayValues(item) {
        const precision = item.price < 1 ? 5 : 2;
        document.getElementById('hud-price').innerText = `$${item.price.toLocaleString(undefined, { minimumFractionDigits: precision, maximumFractionDigits: 6 })}`;
        
        const changeEl = document.getElementById('hud-change');
        changeEl.innerText = `${item.changePct >= 0 ? '+' : ''}${item.changePct.toFixed(2)}%`;
        changeEl.className = `text-sm font-mono font-bold ${item.changePct >= 0 ? 'text-[#14d38a]' : 'text-[#ff4d6a]'}`;

        document.getElementById('hud-high').innerText = `$${(item.high || 0).toLocaleString(undefined, priceFmt(item.high || 0))}`;
        document.getElementById('hud-low').innerText = `$${(item.low || 0).toLocaleString(undefined, priceFmt(item.low || 0))}`;
        document.getElementById('hud-volume').innerText = `$${formatCompact(item.volume)}`;

        const badge = document.getElementById('chart-market-badge');
        badge.innerText = item.isFutures ? 'Perpetual Futures' : 'Spot Cash';
        badge.className = item.isFutures ? 'text-[9px] font-bold uppercase px-1.5 py-0.5 rounded bg-amber-500/10 text-amber-400 border border-amber-500/20' : 'text-[9px] font-bold uppercase px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-400 border border-emerald-500/20';

        updateRangeBar(item);
    }

    // ---------- Indicator math ----------


// ==== 05-indicators.js ====
// ---------- Technical indicator math: SMA, Bollinger Bands, RSI, EMA, VWAP, MACD, Heikin Ashi. ----------
    function calculateSMA(data, count) {
        const result = [];
        if (data.length < count) return result;
        for (let i = 0; i < data.length; i++) {
            if (i < count - 1) continue;
            let sum = 0;
            for (let j = 0; j < count; j++) sum += data[i - j].close;
            result.push({ time: data[i].time, value: sum / count });
        }
        return result;
    }

    function calculateBollingerBands(data, period = 20, multiplier = 2) {
        const upperBand = [];
        const basisBand = [];
        const lowerBand = [];
        
        if (data.length < period) return { upper: [], basis: [], lower: [] };

        for (let i = 0; i < data.length; i++) {
            if (i < period - 1) continue;
            
            let sum = 0;
            for (let j = 0; j < period; j++) sum += data[i - j].close;
            const mean = sum / period;
            
            let variance = 0;
            for (let j = 0; j < period; j++) variance += Math.pow(data[i - j].close - mean, 2);
            const stdDev = Math.sqrt(variance / period);
            
            basisBand.push({ time: data[i].time, value: mean });
            upperBand.push({ time: data[i].time, value: mean + (multiplier * stdDev) });
            lowerBand.push({ time: data[i].time, value: mean - (multiplier * stdDev) });
        }
        return { upper: upperBand, basis: basisBand, lower: lowerBand };
    }

    function calculateRSI(data, period = 14) {
        const result = [];
        if (data.length < period + 1) return result;
        let gains = 0, losses = 0;
        for (let i = 1; i <= period; i++) {
            const diff = data[i].close - data[i - 1].close;
            if (diff >= 0) gains += diff; else losses -= diff;
        }
        let avgGain = gains / period;
        let avgLoss = losses / period;
        result.push({ time: data[period].time, value: avgLoss === 0 ? 100 : 100 - (100 / (1 + (avgGain / avgLoss))) });

        for (let i = period + 1; i < data.length; i++) {
            const diff = data[i].close - data[i - 1].close;
            const gain = diff > 0 ? diff : 0;
            const loss = diff < 0 ? -diff : 0;
            avgGain = ((avgGain * (period - 1)) + gain) / period;
            avgLoss = ((avgLoss * (period - 1)) + loss) / period;
            const rs = avgLoss === 0 ? 100 : avgGain / avgLoss;
            const rsiVal = avgLoss === 0 ? 100 : 100 - (100 / (1 + rs));
            result.push({ time: data[i].time, value: rsiVal });
        }
        return result;
    }

    // ---------- EMA / VWAP / MACD / Heikin Ashi ----------
    function calculateEMA(data, period) {
        const result = [];
        if (data.length < period) return result;
        let sum = 0;
        for (let i = 0; i < period; i++) sum += data[i].close;
        let ema = sum / period;
        result.push({ time: data[period - 1].time, value: ema });
        const k = 2 / (period + 1);
        for (let i = period; i < data.length; i++) {
            ema = data[i].close * k + ema * (1 - k);
            result.push({ time: data[i].time, value: ema });
        }
        return result;
    }

    function calculateVWAP(data) {
        const result = [];
        let cumPV = 0, cumVol = 0;
        data.forEach(c => {
            const typical = (c.high + c.low + c.close) / 3;
            cumPV += typical * c.volume;
            cumVol += c.volume;
            result.push({ time: c.time, value: cumVol > 0 ? cumPV / cumVol : typical });
        });
        return result;
    }

    // Index-aligned EMA over a plain number array — used internally by MACD so the fast/slow/
    // signal lines can be combined by array position without re-deriving time lookups.
    function emaSeriesAligned(values, period) {
        const out = new Array(values.length).fill(null);
        if (values.length < period) return out;
        let sum = 0;
        for (let i = 0; i < period; i++) sum += values[i];
        let ema = sum / period;
        out[period - 1] = ema;
        const k = 2 / (period + 1);
        for (let i = period; i < values.length; i++) {
            ema = values[i] * k + ema * (1 - k);
            out[i] = ema;
        }
        return out;
    }

    function calculateMACD(data, fast = 12, slow = 26, signalPeriod = 9) {
        const closes = data.map(c => c.close);
        const emaFast = emaSeriesAligned(closes, fast);
        const emaSlow = emaSeriesAligned(closes, slow);
        const macdRaw = closes.map((_, i) => (emaFast[i] !== null && emaSlow[i] !== null) ? emaFast[i] - emaSlow[i] : null);

        const macdValues = [];
        const macdValueDataIdx = [];
        macdRaw.forEach((v, i) => { if (v !== null) { macdValues.push(v); macdValueDataIdx.push(i); } });
        const signalDense = emaSeriesAligned(macdValues, signalPeriod);

        const macdLine = [], signalLine = [], histogram = [];
        macdRaw.forEach((v, i) => { if (v !== null) macdLine.push({ time: data[i].time, value: v }); });
        signalDense.forEach((v, j) => {
            if (v === null) return;
            const dataIdx = macdValueDataIdx[j];
            signalLine.push({ time: data[dataIdx].time, value: v });
            const hist = macdRaw[dataIdx] - v;
            histogram.push({ time: data[dataIdx].time, value: hist, color: hist >= 0 ? 'rgba(20, 211, 138, 0.6)' : 'rgba(255, 77, 106, 0.6)' });
        });
        return { macdLine, signalLine, histogram };
    }

    // Heikin Ashi candles are derived from real OHLC but smooth out noise. Indicators (MA/RSI/
    // MACD/etc.) still compute off the real cachedCandlesArray, matching how Binance's chart
    // behaves — only the candle body rendering changes, not the underlying math.
    function computeHeikinAshiSeries(candles) {
        const result = [];
        let prevHA = null;
        candles.forEach(c => {
            const haClose = (c.open + c.high + c.low + c.close) / 4;
            const haOpen = prevHA ? (prevHA.open + prevHA.close) / 2 : (c.open + c.close) / 2;
            const haHigh = Math.max(c.high, haOpen, haClose);
            const haLow = Math.min(c.low, haOpen, haClose);
            const ha = { time: c.time, open: haOpen, high: haHigh, low: haLow, close: haClose };
            result.push(ha);
            prevHA = ha;
        });
        return result;
    }

    // Shared by both the WebSocket kline handler and the REST polling fallback below, so a
    // live candle update always looks identical no matter which transport delivered it.

    // Average True Range: measures volatility (not direction) — the average of the "true range"
    // (the largest of high-low, |high-prevClose|, |low-prevClose|) over the period, smoothed
    // with Wilder's method (same smoothing RSI uses).
    function calculateATR(data, period = 14) {
        if (data.length < period + 1) return [];
        const trueRanges = [];
        for (let i = 1; i < data.length; i++) {
            const c = data[i], p = data[i - 1];
            const tr = Math.max(c.high - c.low, Math.abs(c.high - p.close), Math.abs(c.low - p.close));
            trueRanges.push({ time: c.time, value: tr });
        }
        const result = [];
        let atr = trueRanges.slice(0, period).reduce((s, t) => s + t.value, 0) / period;
        result.push({ time: trueRanges[period - 1].time, value: atr });
        for (let i = period; i < trueRanges.length; i++) {
            atr = (atr * (period - 1) + trueRanges[i].value) / period;
            result.push({ time: trueRanges[i].time, value: atr });
        }
        return result;
    }

    // Stochastic RSI: applies the %K/%D stochastic formula to RSI values instead of price —
    // more sensitive than plain RSI, commonly used to spot momentum turns earlier.
    function calculateStochRSI(data, rsiPeriod = 14, stochPeriod = 14, kSmooth = 3, dSmooth = 3) {
        const rsi = calculateRSI(data, rsiPeriod);
        if (rsi.length < stochPeriod) return { k: [], d: [] };

        const rawK = [];
        for (let i = stochPeriod - 1; i < rsi.length; i++) {
            const window = rsi.slice(i - stochPeriod + 1, i + 1).map(r => r.value);
            const lo = Math.min(...window), hi = Math.max(...window);
            const val = hi - lo === 0 ? 0 : ((rsi[i].value - lo) / (hi - lo)) * 100;
            rawK.push({ time: rsi[i].time, value: val });
        }

        function stochSma(series, n) {
            const out = [];
            for (let i = n - 1; i < series.length; i++) {
                const avg = series.slice(i - n + 1, i + 1).reduce((s, p) => s + p.value, 0) / n;
                out.push({ time: series[i].time, value: avg });
            }
            return out;
        }

        const k = stochSma(rawK, kSmooth);
        const d = stochSma(k, dSmooth);
        return { k, d };
    }


// ==== 06-chart-engine.js ====
// ---------- TradingView Lightweight Charts setup, RSI/MACD sub-panels, order book + trades streams. ----------
    function applyLiveCandle(liveCandle) {
        if (!candlestickSeries || !volumeSeries) return;
        candlestickSeries.update(liveCandle);
        if (lineSeries) lineSeries.update({ time: liveCandle.time, value: liveCandle.close });
        volumeSeries.update({
            time: liveCandle.time, value: liveCandle.volume,
            color: liveCandle.close >= liveCandle.open ? 'rgba(20, 211, 138, 0.2)' : 'rgba(255, 77, 106, 0.2)'
        });

        const matchIndex = cachedCandlesArray.findIndex(c => c.time === liveCandle.time);
        if (matchIndex !== -1) {
            cachedCandlesArray[matchIndex] = liveCandle;
        } else {
            cachedCandlesArray.push(liveCandle);
            if (cachedCandlesArray.length > 400) cachedCandlesArray.shift();
        }

        // Recompute the (cheap, <=400 candle) Heikin Ashi series so the current bar reflects the
        // live update; historical HA bars are deterministic from raw OHLC so recompute is safe.
        haCandlesArray = computeHeikinAshiSeries(cachedCandlesArray);
        if (currentChartType === 'heikinashi' && candlestickSeries && haCandlesArray.length) {
            candlestickSeries.update(haCandlesArray[haCandlesArray.length - 1]);
        }

        updateIndicatorsData();
        updateLegendText(liveCandle);
    }

    // ---------- REST polling fallback ----------
    // Some networks/browsers silently block persistent WebSocket connections while ordinary
    // HTTPS requests go through fine — the page loads once and then just never updates, which
    // looks identical to "the chart is frozen." Polling doesn't depend on a long-lived
    // connection at all, so it works even when WebSockets can't. It runs *in addition to* the
    // WebSocket paths above (harmless if both are active — poll updates are idempotent) and is
    // what actually guarantees the price keeps moving without a manual refresh.
    let chartPollTimer = null;
    let gridPollTimer = null;
    let bookPollTimer = null;
    let tradesPollTimer = null;

    function startChartPolling() {
        if (chartPollTimer) clearInterval(chartPollTimer);
        const myToken = chartRequestToken;
        chartPollTimer = setInterval(async () => {
            if (myToken !== chartRequestToken || !selectedAsset) { clearInterval(chartPollTimer); return; }
            try {
                const endpoint = selectedAsset.isFutures
                    ? `https://fapi.binance.com/fapi/v1/klines?symbol=${selectedAsset.symbol}&interval=${currentInterval}&limit=2`
                    : `https://api.binance.com/api/v3/klines?symbol=${selectedAsset.symbol}&interval=${currentInterval}&limit=2`;
                const res = await fetchWithTimeout(endpoint, 8000);
                if (myToken !== chartRequestToken || !res.ok) return;
                const data = await res.json();
                if (myToken !== chartRequestToken || !Array.isArray(data) || data.length === 0) return;
                const d = data[data.length - 1];
                applyLiveCandle({
                    time: Math.floor(d[0] / 1000),
                    open: parseFloat(d[1]),
                    high: parseFloat(d[2]),
                    low: parseFloat(d[3]),
                    close: parseFloat(d[4]),
                    volume: parseFloat(d[5])
                });
                touchWatchdog('chart');
                const feedDot = document.getElementById('chart-feed-dot');
                if (feedDot && feedDot.className.indexOf('status-live') === -1) feedDot.className = 'status-dot status-live';
            } catch (e) { /* transient network hiccup — next tick will retry */ }
        }, 4000);
    }

    async function refreshMarketSnapshots() {
        if (Object.keys(marketMap).length === 0) return;
        try {
            const [spotRaw, futuresRaw] = await Promise.all([fetchSpotSnapshot(), fetchFuturesSnapshot()]);
            const apply = (arr, isFutures) => {
                if (!Array.isArray(arr)) return;
                arr.filter(item => item && typeof item.symbol === 'string' && item.symbol.endsWith('USDT')).forEach(item => {
                    const idKey = `${item.symbol.toUpperCase()}_${isFutures ? 'F' : 'S'}`;
                    const asset = marketMap[idKey];
                    if (!asset) return;
                    const oldPrice = asset.price;
                    asset.price = parseFloat(item.lastPrice) || asset.price;
                    asset.changePct = parseFloat(item.priceChangePercent) || asset.changePct;
                    asset.high = parseFloat(item.highPrice) || asset.high;
                    asset.low = parseFloat(item.lowPrice) || asset.low;
                    asset.volume = parseFloat(item.quoteVolume) || asset.volume;
                    updateDOMRowRealtime(asset, oldPrice);
                    if (selectedAsset && selectedAsset.id === idKey) updateHUDDisplayValues(asset);
                    checkPriceAlerts(asset);
                });
            };
            apply(spotRaw, false);
            apply(futuresRaw, true);
        } catch (e) { /* transient — next tick will retry */ }
    }

    function startBookAndTradesPolling() {
        if (bookPollTimer) clearInterval(bookPollTimer);
        if (tradesPollTimer) clearInterval(tradesPollTimer);
        const myAssetId = selectedAsset ? selectedAsset.id : null;
        if (!myAssetId) return;

        bookPollTimer = setInterval(async () => {
            if (!selectedAsset || selectedAsset.id !== myAssetId) { clearInterval(bookPollTimer); return; }
            try {
                const endpoint = selectedAsset.isFutures
                    ? `https://fapi.binance.com/fapi/v1/depth?symbol=${selectedAsset.symbol}&limit=10`
                    : `https://api.binance.com/api/v3/depth?symbol=${selectedAsset.symbol}&limit=10`;
                const res = await fetchWithTimeout(endpoint, 8000);
                if (!res.ok || !selectedAsset || selectedAsset.id !== myAssetId) return;
                const data = await res.json();
                if (!selectedAsset || selectedAsset.id !== myAssetId) return;
                renderOrderBook(data.bids || [], data.asks || []);
                touchWatchdog('depth');
                const dot = document.getElementById('depth-status');
                if (dot && dot.className.indexOf('status-live') === -1) dot.className = 'status-dot status-live';
            } catch (e) { /* ignore, retry next tick */ }
        }, 3000);

        tradesPollTimer = setInterval(async () => {
            if (!selectedAsset || selectedAsset.id !== myAssetId) { clearInterval(tradesPollTimer); return; }
            try {
                const endpoint = selectedAsset.isFutures
                    ? `https://fapi.binance.com/fapi/v1/trades?symbol=${selectedAsset.symbol}&limit=5`
                    : `https://api.binance.com/api/v3/trades?symbol=${selectedAsset.symbol}&limit=5`;
                const res = await fetchWithTimeout(endpoint, 8000);
                if (!res.ok || !selectedAsset || selectedAsset.id !== myAssetId) return;
                const data = await res.json();
                if (!Array.isArray(data) || !selectedAsset || selectedAsset.id !== myAssetId) return;
                data.forEach(t => renderTrade({ p: t.price, q: t.qty, m: t.isBuyerMaker, T: t.time }));
                touchWatchdog('trades');
                const dot = document.getElementById('trades-status');
                if (dot && dot.className.indexOf('status-live') === -1) dot.className = 'status-dot status-live';
            } catch (e) { /* ignore, retry next tick */ }
        }, 5000);
    }

    setInterval(refreshMarketSnapshots, 10000);


    async function initializeAssetChartEngine() {
        if (!selectedAsset) return;
        const myToken = ++chartRequestToken;
        if (chartReconnectTimeout) clearTimeout(chartReconnectTimeout);
        if (chartSocket) { chartSocket.onclose = null; try { chartSocket.close(); } catch (e) {} chartSocket = null; }
        if (compareSocket) { compareSocket.onclose = null; try { compareSocket.close(); } catch (e) {} compareSocket = null; }
        compareSeries = null; compareCandles = []; compareSymbol = null;
        const compareClearBtn = document.getElementById('compare-clear-btn');
        if (compareClearBtn) compareClearBtn.classList.add('hidden');

        document.getElementById('chart-title').innerText = `${selectedAsset.baseAsset}/USDT`;
        document.getElementById('chart-ticker-sym').innerText = `Matrix engine tracking: ${selectedAsset.symbol} (${currentInterval})`;
        document.getElementById('legend-sym').innerText = selectedAsset.symbol;

        const restEndpoint = selectedAsset.isFutures
            ? `https://fapi.binance.com/fapi/v1/klines?symbol=${selectedAsset.symbol}&interval=${currentInterval}&limit=300`
            : `https://api.binance.com/api/v3/klines?symbol=${selectedAsset.symbol}&interval=${currentInterval}&limit=300`;

        try {
            container.innerHTML = `<div class="flex flex-col items-center gap-2 text-gray-500 text-xs"><div class="animate-spin rounded-full h-5 w-5 border-b-2 border-[#14d38a]"></div>Loading ${selectedAsset.symbol} ${selectedAsset.isFutures ? 'futures' : 'spot'} candles...</div>`;

            const res = await fetchWithTimeout(restEndpoint, 12000);
            if (myToken !== chartRequestToken) return; // a newer selection superseded this request

            if (!res.ok) throw new Error(`Kline API responded with status ${res.status}`);
            const data = await res.json();
            if (myToken !== chartRequestToken) return;

            if (data && !Array.isArray(data) && data.code) {
                throw new Error(`Kline API error ${data.code}: ${data.msg || 'unknown error'}`);
            }
            if (!Array.isArray(data) || data.length === 0) {
                throw new Error('No candle data returned for this symbol/interval.');
            }

            cachedCandlesArray = data.map(d => ({
                time: Math.floor(d[0] / 1000),
                open: parseFloat(d[1]),
                high: parseFloat(d[2]),
                low: parseFloat(d[3]),
                close: parseFloat(d[4]),
                volume: parseFloat(d[5])
            }));
            haCandlesArray = computeHeikinAshiSeries(cachedCandlesArray);

            if (chartInstance) {
                if (resizeObserver) resizeObserver.disconnect();
                chartInstance.remove();
                chartInstance = null;
            }
            if (rsiChartInstance) { rsiChartInstance.remove(); rsiChartInstance = null; }
            if (macdChartInstance) { macdChartInstance.remove(); macdChartInstance = null; }

            container.innerHTML = '';
            ohlvLegend.classList.remove('hidden');

            chartInstance = LightweightCharts.createChart(container, {
                layout: { background: { color: '#12141c' }, textColor: '#848e9c', fontSize: 11, fontFamily: 'monospace' },
                grid: { vertLines: { color: '#2b2f3a' }, horzLines: { color: '#2b2f3a' } },
                crosshair: {
                    mode: LightweightCharts.CrosshairMode.Normal,
                    vertLine: { labelBackgroundColor: '#474d57', color: '#5e6673', style: 3 },
                    horzLine: { labelBackgroundColor: '#474d57', color: '#5e6673', style: 3 },
                },
                rightPriceScale: { borderColor: '#2b2f3a', autoScale: true, mode: isLogScale ? LightweightCharts.PriceScaleMode.Logarithmic : LightweightCharts.PriceScaleMode.Normal },
                leftPriceScale: { borderColor: '#2b2f3a', visible: false },
                timeScale: { borderColor: '#2b2f3a', timeVisible: true },
                watermark: { visible: true, text: selectedAsset.symbol, fontSize: 42, color: 'rgba(255,255,255,0.045)', horzAlign: 'center', vertAlign: 'center' },
            });

            candlestickSeries = chartInstance.addCandlestickSeries({
                upColor: '#14d38a', downColor: '#ff4d6a', borderVisible: false,
                wickUpColor: '#14d38a', wickDownColor: '#ff4d6a',
                visible: currentChartType === 'candles' || currentChartType === 'heikinashi'
            });
            candlestickSeries.setData(currentChartType === 'heikinashi' ? haCandlesArray : cachedCandlesArray);

            lineSeries = chartInstance.addLineSeries({
                color: '#14d38a', lineWidth: 2, priceLineVisible: false, crosshairMarkerVisible: true,
                visible: currentChartType === 'line'
            });
            lineSeries.setData(cachedCandlesArray.map(c => ({ time: c.time, value: c.close })));

            // Tech Overlays Integration Pipeline
            // lastValueVisible:false — without it, every active overlay stamps its own
            // colored "last value" badge on the right price axis (in addition to its
            // line on the chart). With several overlays on at once these badges stack
            // up and collide with each other and with the axis's own price ticks —
            // the "labels overlapping the price scale" glitch. The line + the toolbar
            // pill already identify each overlay, so the axis badge is redundant.
            ma7Series = chartInstance.addLineSeries({ color: '#e5b324', lineWidth: 1.5, title: 'MA(7)', priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false });
            ma25Series = chartInstance.addLineSeries({ color: '#24a0e5', lineWidth: 1.5, title: 'MA(25)', priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false });
            ema12Series = chartInstance.addLineSeries({ color: '#ec4899', lineWidth: 1.5, title: 'EMA(12)', priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false });
            ema26Series = chartInstance.addLineSeries({ color: '#22d3ee', lineWidth: 1.5, title: 'EMA(26)', priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false });
            vwapSeries = chartInstance.addLineSeries({ color: '#fbbf24', lineWidth: 1.5, lineStyle: 2, title: 'VWAP', priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false });
            
            bbUpperSeries = chartInstance.addLineSeries({ color: 'rgba(168, 85, 247, 0.6)', lineWidth: 1, title: 'BB Upper', priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false });
            bbBasisSeries = chartInstance.addLineSeries({ color: 'rgba(168, 85, 247, 0.3)', lineWidth: 1, lineStyle: 2, title: 'BB Basis', priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false });
            bbLowerSeries = chartInstance.addLineSeries({ color: 'rgba(168, 85, 247, 0.6)', lineWidth: 1, title: 'BB Lower', priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false });

            volumeSeries = chartInstance.addHistogramSeries({ 
                priceFormat: { type: 'volume' }, 
                priceScaleId: 'left', 
                priceLineVisible: false 
            });
            chartInstance.priceScale('left').applyOptions({ scaleMargins: { top: 0.8, bottom: 0 } });
            
            volumeSeries.setData(cachedCandlesArray.map(c => ({
                time: c.time, value: c.volume, color: c.close >= c.open ? 'rgba(20, 211, 138, 0.2)' : 'rgba(255, 77, 106, 0.2)'
            })));

            setupRSIPanel();
            setupMACDPanel();
            setupATRPanel();
            setupStochPanel();
            updateIndicatorsData();
            updateChartOverlayLines();

            updateLegendText(cachedCandlesArray[cachedCandlesArray.length - 1]);

            chartInstance.subscribeCrosshairMove(param => {
                if (!param || !param.time || param.point === undefined) {
                    if (cachedCandlesArray.length) updateLegendText(cachedCandlesArray[cachedCandlesArray.length - 1]);
                    return;
                }
                const candle = param.seriesData.get(currentChartType === 'candles' ? candlestickSeries : lineSeries);
                const vol = param.seriesData.get(volumeSeries);
                if (candle && candle.open !== undefined) {
                    updateLegendText({ open: candle.open, high: candle.high, low: candle.low, close: candle.close, volume: vol ? vol.value : 0 });
                } else if (candle && candle.value !== undefined) {
                    updateLegendText({ open: candle.value, high: candle.value, low: candle.value, close: candle.value, volume: vol ? vol.value : 0 });
                }
            });

            chartInstance.timeScale().fitContent();

            chartInstance.timeScale().subscribeVisibleLogicalRangeChange(range => {
                if (syncingRange || !range) return;
                syncingRange = true;
                if (rsiChartInstance) rsiChartInstance.timeScale().setVisibleLogicalRange(range);
                if (macdChartInstance) macdChartInstance.timeScale().setVisibleLogicalRange(range);
                syncingRange = false;
            });
            
            resizeObserver = new ResizeObserver(entries => {
                if (chartInstance && entries[0].contentRect.width > 0) {
                    chartInstance.resize(entries[0].contentRect.width, 400);
                    if (rsiChartInstance) rsiChartInstance.resize(entries[0].contentRect.width, 110);
                    if (macdChartInstance) macdChartInstance.resize(entries[0].contentRect.width, 110);
                }
            });
            resizeObserver.observe(container);

            connectLiveChartWebSocket(selectedAsset.symbol, selectedAsset.isFutures);
            startChartPolling();

        } catch (err) {
            if (myToken !== chartRequestToken) return;
            console.error("Historical trace failure:", err);
            container.innerHTML = `<div class="flex flex-col items-center gap-2 text-center px-4"><span class="text-[#ff4d6a] text-xs font-bold">Could not load ${selectedAsset.isFutures ? 'futures' : 'spot'} chart for ${selectedAsset.symbol}</span><span class="text-gray-500 text-[10px]">${(err && err.message) ? err.message : 'Unknown error'} — retrying in 5s</span></div>`;
            chartReconnectTimeout = setTimeout(() => { if (myToken === chartRequestToken) initializeAssetChartEngine(); }, 5000);
        }
    }

